'use client';

/* eslint-disable @typescript-eslint/no-explicit-any */
import { useEffect, useRef, useState, type FormEvent } from 'react';
import { useDemoSession } from '@/lib/use-demo-session';
import { AuthControls } from '@/components/auth-controls';
import { ResourceKanban } from '@/components/resource-kanban';

type AnyRow = Record<string, any>;
type View = 'overview' | 'products' | 'stock' | 'receipts' | 'deliveries' | 'transfers' | 'adjustments' | 'ledger' | 'reports' | 'team' | 'warehouses' | 'categories' | 'suppliers';
type Option = { id: string; name: string };

const record = (value: unknown): AnyRow => value !== null && typeof value === 'object' ? value as AnyRow : {};
const stringValue = (value: unknown, fallback = ''): string => typeof value === 'string' ? value : fallback;
const numericValue = (value: unknown): number => typeof value === 'number' ? value : Number(value || 0);
const listValue = (value: unknown): AnyRow[] => Array.isArray(value) ? value.map(record) : [];
const child = (row: AnyRow, key: string): AnyRow => record(row[key]);
const txt = (row: AnyRow, key: string, fallback = ''): string => stringValue(row[key], fallback);
const num = (row: AnyRow, key: string): number => numericValue(row[key]);
const array = (row: AnyRow, key: string): AnyRow[] => listValue(row[key]);
const nav: { id: View; label: string; icon: string }[] = [
  { id: 'overview', label: 'Overview', icon: '◫' }, { id: 'products', label: 'Products', icon: '▤' }, { id: 'stock', label: 'Stock levels', icon: '▦' },
  { id: 'receipts', label: 'Receipts', icon: '↙' }, { id: 'deliveries', label: 'Deliveries', icon: '↗' }, { id: 'transfers', label: 'Transfers', icon: '⇄' },
  { id: 'adjustments', label: 'Adjustments', icon: '±' }, { id: 'ledger', label: 'Stock ledger', icon: '≋' }, { id: 'reports', label: 'Reports', icon: '⌁' },
];
const managementNav: { id: View; label: string; icon: string }[] = [{ id: 'warehouses', label: 'Warehouses', icon: '⌂' }, { id: 'categories', label: 'Categories', icon: '◇' }, { id: 'suppliers', label: 'Suppliers', icon: '⇢' }, { id: 'team', label: 'Team', icon: '♧' }];
const api = async (path: string, init?: RequestInit): Promise<any> => {
  const response = await fetch(`/api/${path}`, { ...init, headers: { ...(init?.body ? { 'content-type': 'application/json' } : {}), ...init?.headers } });
  if (!response.ok) { const result = await response.json().catch(() => ({})); throw new Error(result.error || `Request failed (${response.status})`); }
  return response.headers.get('content-type')?.includes('text/csv') ? response.blob() : response.json();
};
const money = (n: number | string | null | undefined) => new Intl.NumberFormat('en-US', { style: 'currency', currency: 'USD', maximumFractionDigits: 0 }).format(Number(n || 0));
const date = (value?: string) => value ? new Date(value).toLocaleDateString('en-US', { month: 'short', day: 'numeric', year: 'numeric' }) : '—';
const count = (value?: number) => new Intl.NumberFormat('en-US').format(value || 0);
const titleCase = (value = '') => value.replaceAll('_', ' ').replace(/\b\w/g, (c) => c.toUpperCase());

export function DashboardApp() {
  const [user, setUser] = useState<AnyRow | null>(null);
  const [isLoaded, setIsLoaded] = useState(false);
  const demoSession = useDemoSession();
  const [movementData, setMovementData] = useState<AnyRow[]>([]);
  const [view, setView] = useState<View>('overview');
  const [summary, setSummary] = useState<AnyRow | null>(null);
  const [warehouse, setWarehouse] = useState('');
  const [notice, setNotice] = useState<{ type: 'success' | 'error'; text: string } | null>(null);
  const [busy, setBusy] = useState(false);
  const [mobileMenu, setMobileMenu] = useState(false);
  const [query, setQuery] = useState('');
  const [refresh, setRefresh] = useState(0);
  const [modal, setModal] = useState<View | null>(null);
  const [selected, setSelected] = useState<AnyRow | null>(null);
  const [days, setDays] = useState(30);
  const searchInput = useRef<HTMLInputElement>(null);

  const notify = (text: string, type: 'success' | 'error' = 'success') => { setNotice({ text, type }); window.setTimeout(() => setNotice(null), 4500); };
  const reload = () => setRefresh((x) => x + 1);
  useEffect(() => { api('auth/me').then((result) => setUser({ ...result.user, fullName: [result.user.firstName, result.user.lastName].filter(Boolean).join(' ') })).catch(() => undefined).finally(() => setIsLoaded(true)); }, []);
  useEffect(() => { api(`dashboard/kpis${warehouse ? `?warehouseId=${warehouse}` : ''}`).then(setSummary).catch((error) => notify(error.message, 'error')); api('reports/movements?days=30').then(setMovementData).catch((error) => notify(error.message, 'error')); }, [warehouse, refresh]);
  useEffect(() => { const id = window.setInterval(reload, 30_000); return () => window.clearInterval(id); }, []);
  useEffect(() => {
    const focusSearch = (event: KeyboardEvent) => {
      const target = event.target as HTMLElement | null;
      const editing = target?.isContentEditable || ['INPUT', 'TEXTAREA', 'SELECT'].includes(target?.tagName || '');
      if (!editing && ((event.key.toLowerCase() === 'k' && (event.metaKey || event.ctrlKey)) || event.key === '/')) {
        event.preventDefault();
        searchInput.current?.focus();
      }
    };
    window.addEventListener('keydown', focusSearch);
    return () => window.removeEventListener('keydown', focusSearch);
  }, []);
  const headline = view === 'overview' ? 'Inventory overview' : nav.concat(managementNav).find((item) => item.id === view)?.label ?? titleCase(view);
  const closeModal = () => { setModal(null); setSelected(null); };
  const canCreate = isLoaded && (view === 'team' ? user?.role === 'admin' : user?.role === 'staff' ? ['receipts', 'deliveries'].includes(view) : Boolean(user?.role));
  const changeView = (next: View) => { setView(next); setMobileMenu(false); setQuery(''); };

  const doAction = async (path: string, body?: unknown, method = 'POST', message = 'Changes saved.') => {
    setBusy(true);
    try { await api(path, { method, ...(body ? { body: JSON.stringify(body) } : {}) }); notify(message); closeModal(); reload(); }
    catch (error) { notify(error instanceof Error ? error.message : 'Something went wrong.', 'error'); }
    finally { setBusy(false); }
  };

  return <div className="app-shell">
    <aside className={`sidebar ${mobileMenu ? 'sidebar-open' : ''}`}>
      <button className="brand" onClick={() => changeView('overview')} aria-label="StockSense overview"><span className="brand-mark">S</span><span className="brand-name">StockSense</span></button>
      <div className="workspace-switch"><div className="workspace-avatar">{(user?.firstName || user?.email || 'S').slice(0, 1).toUpperCase()}</div><div className="workspace-copy"><strong>{user?.firstName ? `${user.firstName}'s workspace` : 'Your workspace'}</strong><span>Inventory operations</span></div><span className="switch-chevron">⌄</span></div>
      <nav className="side-nav" aria-label="Main navigation"><span className="nav-caption">WORKSPACE</span>{nav.map((item) => <NavButton key={item.id} item={item} selected={view === item.id} onClick={() => changeView(item.id)} />)}<span className="nav-caption nav-caption-lower">MANAGE</span>{managementNav.map((item) => <NavButton key={item.id} item={item} selected={view === item.id} onClick={() => changeView(item.id)} />)}</nav>
      <div className="sidebar-bottom">{demoSession && <div className="demo-session-card"><span>LOCAL DEMO ROLE</span><strong>{demoSession.role[0].toUpperCase() + demoSession.role.slice(1)}</strong><button onClick={() => { void demoSession.switchRole(); }}>Switch role</button><button onClick={() => { void demoSession.signOut(); }}>Exit demo</button></div>}<div className="help-block"><span className="help-icon">?</span><div><strong>Need a hand?</strong><span>Explore the quick guide</span></div><span className="help-arrow">↗</span></div><div className="account-row">{!demoSession && <><AuthControls /><div className="account-copy"><strong>{isLoaded ? user?.fullName || 'Account' : 'Loading…'}</strong><span>{user?.email}</span></div></>}</div></div>
    </aside>
    {mobileMenu && <button className="mobile-scrim" aria-label="Close navigation" onClick={() => setMobileMenu(false)} />}
    <main className="main-column">
      <header className="topbar"><button className="mobile-menu" onClick={() => setMobileMenu(!mobileMenu)} aria-label="Toggle navigation">☰</button><div className="breadcrumb">Workspace <span>/</span> <strong>{headline}</strong></div><div className="topbar-actions"><label className="global-search"><span>⌕</span><input ref={searchInput} aria-label={`Search ${headline.toLowerCase()}`} placeholder={`Search ${headline.toLowerCase()}…`} value={query} onChange={(e) => setQuery(e.target.value)} /><kbd>⌘ K</kbd></label><button className="icon-action notification-action" aria-label="Notifications" onClick={() => notify(summary?.lowStock ? `${summary.lowStock} products at or below reorder level.` : 'You are all caught up.')}>♧{Boolean(summary?.lowStock) && <i />}</button><button className="top-avatar" aria-label="Account information" title={user?.email || 'Account information'} onClick={() => notify(`Signed in as ${user?.email || 'your account'}.`)}>{user?.firstName?.slice(0, 1) || user?.email?.slice(0, 1) || 'S'}</button></div></header>
      <section className="page-wrap"><div className="page-heading"><div><div className="date-context">{new Date().toLocaleDateString('en-US', { weekday: 'long', month: 'long', day: 'numeric' })}</div><h1>{headline}</h1><p>{view === 'overview' ? 'A clear picture of what’s happening across your inventory.' : subtitle(view)}</p></div><div className="heading-actions">{view === 'overview' && <select className="warehouse-select" value={warehouse} onChange={(e) => setWarehouse(e.target.value)} aria-label="Filter by warehouse"><option value="">All warehouses</option>{(summary?.warehouseOptions || []).map((w: Option) => <option key={w.id} value={w.id}>{w.name}</option>)}</select>}<button className="button button-quiet" onClick={() => reload()}>↻ <span>Refresh</span></button>{canCreate && !['ledger', 'reports', 'team'].includes(view) && <button className="button button-primary" onClick={() => { setSelected(null); setModal(view === 'overview' || view === 'products' || view === 'stock' ? 'products' : view); }}>{view === 'overview' || view === 'products' || view === 'stock' ? <><b>＋</b> New product</> : view === 'warehouses' ? <><b>＋</b> New warehouse</> : <><b>＋</b> Create {view === 'receipts' ? 'receipt' : view === 'deliveries' ? 'delivery' : view === 'transfers' ? 'transfer' : view === 'adjustments' ? 'count' : singular(view)}</>}</button>}</div></div>
        {view === 'overview' ? <Overview summary={summary} loading={!summary} movementData={movementData} setView={changeView} openRecord={(row) => setSelected(row)} /> : <ResourceView view={view} query={query} refresh={refresh} warehouse={warehouse} actorRole={user?.role || ''} canCreate={canCreate} days={days} setDays={setDays} notify={notify} doAction={doAction} onCreate={() => { setSelected(null); setModal(view === 'stock' ? 'products' : view); }} onSelect={setSelected} />}
      </section>
      <footer className="app-footer"><span>StockSense <span className="footer-dot">·</span> Local SQL edition</span><span><span className="online-dot" /> Connected to local SQL</span></footer>
    </main>
    {notice && <div className={`toast toast-${notice.type}`} role="status"><span>{notice.type === 'success' ? '✓' : '!'}</span>{notice.text}<button onClick={() => setNotice(null)} aria-label="Dismiss notification">×</button></div>}
    {modal && <DocumentModal type={modal} selected={selected} busy={busy} onRole={user?.role || 'staff'} onClose={closeModal} onSubmit={async (payload) => { const endpoint = modal === 'team' ? 'users' : modal; if (selected) await doAction(`${endpoint}/${selected.id}`, payload, 'PUT'); else await doAction(endpoint, payload, 'POST', modal === 'team' ? 'Clerk invitation sent.' : 'Record created successfully.'); }} />}
    {selected && !modal && <DetailPanel item={selected} onClose={() => setSelected(null)} onAction={async (action) => view === 'team' && action === 'disable' ? doAction(`users/${selected.id}`, undefined, 'DELETE', 'Member access disabled.') : doAction(`${view}/${selected.id}/${action}`, {}, 'POST', `${titleCase(action)} complete.`)} onEdit={modalView(view) && (view !== 'team' || user?.role === 'admin') ? () => { setModal(modalView(view)); setSelected(selected); } : undefined} showDisable={view === 'team' && user?.role === 'admin'} />}
  </div>;
}

function NavButton({ item, selected, onClick }: { item: { id: View; label: string; icon: string }; selected: boolean; onClick: () => void }) { return <button className={`nav-item ${selected ? 'nav-active' : ''}`} onClick={onClick}><span className="nav-icon">{item.icon}</span><span>{item.label}</span></button>; }
function subtitle(view: View) { return ({ products: 'One well-kept catalog, shared by every location.', stock: 'Available units, with every quantity traceable.', receipts: 'Goods arriving into your warehouses.', deliveries: 'Pick, pack, and ship with confidence.', transfers: 'Move inventory between locations.', adjustments: 'Reconcile your shelf count with the system.', ledger: 'Every stock movement, recorded in order.', reports: 'Patterns and detail behind your inventory.', team: 'People, roles, and access to this workspace.', warehouses: 'The physical locations holding your stock.', categories: 'Keep your product catalog grouped and easy to scan.', suppliers: 'Maintain the vendors behind your incoming goods.' } as Record<string, string>)[view] || ''; }

function Overview({ summary, loading, movementData, setView, openRecord }: { summary: AnyRow | null; loading: boolean; movementData: AnyRow[]; setView: (v: View) => void; openRecord: (v: AnyRow) => void }) {
  const kpis = [
    { label: 'Active products', value: summary?.products, format: count, icon: '▤', tone: 'slate', hint: 'Across your catalog' },
    { label: 'Units on hand', value: summary?.unitsInStock, format: count, icon: '▦', tone: 'blue', hint: `${count(summary?.warehouses)} active locations` },
    { label: 'Needs attention', value: summary?.lowStock, format: count, icon: '⌁', tone: 'amber', hint: `${count(summary?.outOfStock)} currently out of stock` },
    { label: 'Inventory value', value: summary?.stockValue, format: money, icon: '$', tone: 'green', hint: 'At recorded cost price' },
  ];
  return <>
    <div className="kpi-grid">{kpis.map((kpi) => <article className="kpi-card" key={kpi.label}><div className={`kpi-icon icon-${kpi.tone}`}>{kpi.icon}</div><div className="kpi-label">{kpi.label}<span className="info-dot" title={kpi.hint}>i</span></div><div className="kpi-value">{loading ? <span className="skeleton skeleton-number" /> : kpi.format(kpi.value)}</div><div className="kpi-hint">{kpi.hint}</div></article>)}</div>
    <div className="overview-grid"><section className="panel movement-panel"><div className="panel-heading"><div><h2>Stock movement</h2><p>A daily view of inventory in and out</p></div><button className="select-like" onClick={() => setView('reports')}>Last 30 days <span aria-hidden="true">↗</span></button></div><MovementChart data={movementData} summary={summary} /></section><section className="panel pipeline-panel"><div className="panel-heading"><div><h2>Open workflows</h2><p>Items waiting for the next step</p></div><span className="small-live"><i /> Live</span></div><div className="workflow-list"><WorkflowLine icon="↙" color="blue" title="Receipts to process" value={summary?.pendingReceipts || 0} onClick={() => setView('receipts')} /><WorkflowLine icon="↗" color="orange" title="Deliveries in progress" value={summary?.pendingDeliveries || 0} onClick={() => setView('deliveries')} /><WorkflowLine icon="⇄" color="violet" title="Transfers awaiting action" value={summary?.pendingTransfers || 0} onClick={() => setView('transfers')} /></div><button className="text-link full-link" onClick={() => setView('receipts')}>View all operations <span>→</span></button></section></div>
    <section className="panel activity-panel"><div className="panel-heading"><div><h2>Recent stock activity</h2><p>Latest changes across your locations</p></div><button className="text-link" onClick={() => setView('ledger')}>Full ledger <span>→</span></button></div><ActivityTable rows={summary?.recentActivity || []} loading={loading} openRecord={openRecord} /></section>
    <section className="attention-banner"><div className="attention-symbol">!</div><div className="attention-copy"><strong>{summary?.lowStock ? `${count(summary.lowStock)} products need a closer look` : 'You’re in good shape'}</strong><span>{summary?.outOfStock ? `${count(summary.outOfStock)} products are out of stock. Review your reorder levels to stay ahead.` : 'No stockouts in the locations selected. We’ll surface any low stock here.'}</span></div><button className="button button-quiet" onClick={() => setView('stock')}>Review stock <span>→</span></button></section>
  </>;
}
function WorkflowLine({ icon, color, title, value, onClick }: { icon: string; color: string; title: string; value: number; onClick: () => void }) { return <button className="workflow-line" onClick={onClick}><span className={`flow-icon flow-${color}`}>{icon}</span><span className="workflow-title">{title}</span><strong>{value}</strong><span className="row-chevron">›</span></button>; }
function MovementChart({ data, summary }: { data: AnyRow[]; summary: AnyRow | null }) { const bars = data.slice(-30); const max = Math.max(1, ...bars.map((day) => Math.max(day.inbound, day.outbound))); return <div className="chart-area"><div className="chart-y-labels"><span>{count(max)}</span><span>{count(Math.round(max * .75))}</span><span>{count(Math.round(max * .5))}</span><span>{count(Math.round(max * .25))}</span><span>0</span></div><div className="chart-plot"><div className="chart-gridlines"><i /><i /><i /><i /><i /></div><div className="chart-bars">{bars.map((day) => <div className="chart-day" key={day.date} title={`${day.date}: ${count(day.inbound)} received, ${count(day.outbound)} shipped`}><span className="bar bar-in" style={{ height: `${Math.max(day.inbound ? 4 : 0, day.inbound / max * 100)}%` }} /><span className="bar bar-out" style={{ height: `${Math.max(day.outbound ? 4 : 0, day.outbound / max * 100)}%` }} /></div>)}</div><div className="chart-x-labels"><span>{bars[0] ? new Date(bars[0].date).toLocaleDateString('en-US', { month: 'short', day: 'numeric' }) : 'No activity'}</span><span>{bars[Math.floor(bars.length / 2)] ? new Date(bars[Math.floor(bars.length / 2)].date).toLocaleDateString('en-US', { month: 'short', day: 'numeric' }) : ''}</span><span>Today</span></div></div><div className="chart-legend"><span><i className="legend-in" /> Received</span><span><i className="legend-out" /> Shipped</span><span className="chart-note">On hand · {count(summary?.unitsInStock)} units</span></div>{bars.length === 0 && <p className="chart-empty">No stock movements in the last 30 days.</p>}</div>; }
function ActivityTable({ rows, loading, openRecord }: { rows: AnyRow[]; loading: boolean; openRecord: (v: AnyRow) => void }) { if (loading) return <div className="loading-table">Loading activity…</div>; if (!rows.length) return <EmptyState title="Nothing has moved yet" text="Your receipts, deliveries, transfers, and adjustments will appear here." />; return <div className="table-scroll"><table><thead><tr><th>Stock movement</th><th>Type</th><th>Location</th><th>Quantity</th><th>When</th><th /></tr></thead><tbody>{rows.slice(0, 6).map((row) => <tr key={row.id} onClick={() => openRecord(row)}><td><div className="activity-product"><span className={`product-dot dot-${row.quantityChange >= 0 ? 'green' : 'red'}`}>{row.quantityChange >= 0 ? '↙' : '↗'}</span><div><strong>{row.product?.name || 'Product'}</strong><small>{row.product?.sku || '—'}</small></div></div></td><td><span className="type-label">{titleCase(row.transactionType)}</span></td><td>{row.warehouse?.name || '—'}</td><td className={row.quantityChange >= 0 ? 'qty-positive' : 'qty-negative'}>{row.quantityChange > 0 ? '+' : ''}{count(row.quantityChange)}</td><td>{date(row.createdAt)}</td><td><span className="table-chevron">›</span></td></tr>)}</tbody></table></div>; }

function ResourceView({ view, query, refresh, warehouse, actorRole, canCreate, days, setDays, notify, doAction, onCreate, onSelect }: { view: View; query: string; refresh: number; warehouse: string; actorRole: string; canCreate: boolean; days: number; setDays: (d: number) => void; notify: (text: string, type?: 'success' | 'error') => void; doAction: (path: string, body?: unknown, method?: string, message?: string) => Promise<void>; onCreate: () => void; onSelect: (v: AnyRow) => void }) {
  const [rows, setRows] = useState<AnyRow[]>([]); const [loading, setLoading] = useState(true); const [error, setError] = useState(''); const [page, setPage] = useState(1); const [total, setTotal] = useState(0); const [categories, setCategories] = useState<Option[]>([]); const [category, setCategory] = useState(''); const [status, setStatus] = useState(''); const [layout, setLayout] = useState<'table' | 'kanban'>('table'); const [refreshKey, setRefreshKey] = useState(0);
  const endpoint = view === 'stock' ? 'stock' : view === 'team' ? 'users' : view;
  const supported = ['products', 'stock', 'receipts', 'deliveries', 'transfers', 'adjustments', 'ledger', 'warehouses', 'team', 'categories', 'suppliers'].includes(view);
  useEffect(() => { api('categories').then(setCategories).catch(() => undefined); }, []);
  useEffect(() => { if (!supported) return; setLoading(true); setError(''); const params = new URLSearchParams({ page: String(page), limit: '50' }); if (query) params.set('q', query); if (view === 'products' && category) params.set('categoryId', category); if (view === 'stock' && warehouse) params.set('warehouseId', warehouse); if (status && ['receipts', 'deliveries', 'transfers', 'adjustments'].includes(view)) params.set('status', status); const path = view === 'team' ? `users${query ? `?q=${encodeURIComponent(query)}` : ''}` : view === 'warehouses' ? `warehouses?includeInactive=true${query ? `&q=${encodeURIComponent(query)}` : ''}` : view === 'categories' || view === 'suppliers' ? `${view}${query ? `?q=${encodeURIComponent(query)}` : ''}` : view === 'ledger' ? `ledger${query ? `?q=${encodeURIComponent(query)}` : ''}` : `${endpoint}?${params}`; api(path).then((result) => { const data = Array.isArray(result) ? result : result.data || []; setRows(data); setTotal(result.total ?? data.length); if (page > 1 && data.length === 0) setPage(page - 1); if (page > 1 && data.length === 0) setPage(page - 1); }).catch((e) => setError(e.message)).finally(() => setLoading(false)); }, [view, query, page, category, warehouse, status, refresh, endpoint, supported, refreshKey]);
  useEffect(() => { setPage(1); }, [view, query, category, status]);
  const onRetry = () => { setRefreshKey((key) => key + 1); };
  if (view === 'reports') return <ReportsView days={days} setDays={setDays} />;
  if (!supported) return <EmptyState title="Not available yet" text="This section is being prepared." />;
  const title = nav.concat(managementNav).find((n) => n.id === view)?.label || 'Inventory';
  const supportsBoard = ['products', 'stock', 'receipts', 'deliveries', 'transfers', 'adjustments', 'team', 'warehouses', 'categories', 'suppliers'].includes(view);
  const handleRowAction = (id: string, action: string) => {
    if (view === 'team' && action.startsWith('role:')) void doAction(`users/${id}/role`, { role: action.slice(5) }, 'PUT', 'Member role updated.');
    else if (view === 'team' && action === 'disable') void doAction(`users/${id}`, undefined, 'DELETE', 'Member access disabled.');
    else void doAction(`${endpoint}/${id}/${action}`, {}, 'POST', `${titleCase(action)} complete.`);
  };
  return <section className="panel data-panel"><div className="data-toolbar"><div className="data-toolbar-start">{canCreate && !['team', 'ledger', 'reports'].includes(view) && <button className="button button-primary" onClick={onCreate}>＋ Create {singular(view)}</button>}{supportsBoard && <div className="view-switch" role="group" aria-label="Choose display"><button type="button" aria-pressed={layout === 'table'} onClick={() => setLayout('table')}>Table</button><button type="button" aria-pressed={layout === 'kanban'} onClick={() => setLayout('kanban')}>Kanban</button></div>}<div className="toolbar-filters">{view === 'products' && <select aria-label="Filter category" value={category} onChange={(e) => setCategory(e.target.value)}><option value="">All categories</option>{categories.map((item) => <option key={item.id} value={item.id}>{item.name}</option>)}</select>}{['receipts', 'deliveries', 'transfers', 'adjustments'].includes(view) && <select aria-label="Filter status" value={status} onChange={(e) => setStatus(e.target.value)}><option value="">All statuses</option>{['draft', 'waiting', 'picking', 'packed', 'approved', 'done', 'delivered', 'completed'].map((s) => <option key={s} value={s}>{titleCase(s)}</option>)}</select>}<span className="result-count">{count(total)} records</span></div></div>{view === 'ledger' && <button className="button button-quiet" onClick={() => { api('ledger/export').then((blob: Blob) => { const url = URL.createObjectURL(blob); const link = document.createElement('a'); link.href = url; link.download = 'stocksense-ledger.csv'; link.click(); window.setTimeout(() => URL.revokeObjectURL(url), 0); }).catch((e) => notify(e.message, 'error')); }}>↓ Export CSV</button>}</div>
    {error ? <div className="error-state"><strong>Couldn’t load {title.toLowerCase()}</strong><p>{error}</p><button className="button button-quiet" onClick={onRetry}>Try again</button></div> : loading ? <div className="loading-table">Loading {title.toLowerCase()}…</div> : !rows.length ? <EmptyState title={`No ${title.toLowerCase()} yet`} text={`When you add ${title.toLowerCase()}, they’ll be listed here.`} action={canCreate ? onCreate : undefined} actionLabel="Create first record" /> : layout === 'kanban' && supportsBoard ? <ResourceKanban view={view as 'products' | 'stock' | 'receipts' | 'deliveries' | 'transfers' | 'adjustments' | 'team' | 'warehouses' | 'categories' | 'suppliers'} rows={rows} onSelect={onSelect} actions={view === 'team' && actorRole === 'admin' ? (row) => <><button className="tiny-action" type="button" onClick={() => onSelect(row)}>Edit</button>{txt(row, 'status') === 'active' && <button className="tiny-action" type="button" onClick={() => handleRowAction(txt(row, 'id'), 'disable')}>Disable</button>}</> : undefined} /> : <div className="table-scroll"><ResourceTable view={view} rows={rows} actorRole={actorRole} onSelect={onSelect} onAction={handleRowAction} /></div>}
    {total > 50 && <div className="pagination"><span>Showing {(page - 1) * 50 + 1}–{Math.min(page * 50, total)} of {count(total)}</span><div><button disabled={page <= 1} onClick={() => setPage((n) => n - 1)}>← Previous</button><button disabled={page * 50 >= total} onClick={() => setPage((n) => n + 1)}>Next →</button></div></div>}
  </section>;
}
function ResourceTable({ view, rows, actorRole, onSelect, onAction }: { view: View; rows: AnyRow[]; actorRole: string; onSelect: (v: AnyRow) => void; onAction: (id: string, action: string) => void }) {
  if (view === 'categories') return <table><thead><tr><th>Category</th><th>Description</th><th>Products</th></tr></thead><tbody>{rows.map((row) => <tr key={txt(row, 'id')} onClick={() => onSelect(row)}><td><strong>{txt(row, 'name')}</strong></td><td>{txt(row, 'description', '—')}</td><td>{numericValue(child(row, '_count').products)}</td></tr>)}</tbody></table>;
  if (view === 'suppliers') return <table><thead><tr><th>Supplier</th><th>Email</th><th>Phone</th><th>Address</th></tr></thead><tbody>{rows.map((row) => <tr key={txt(row, 'id')} onClick={() => onSelect(row)}><td><strong>{txt(row, 'name')}</strong></td><td>{txt(row, 'email', '—')}</td><td>{txt(row, 'phone', '—')}</td><td>{txt(row, 'address', '—')}</td></tr>)}</tbody></table>;
  if (view === 'products') return <table><thead><tr><th>SKU</th><th>Product name</th><th>Category</th><th>On hand</th><th>Reorder at</th><th>Unit cost</th><th>Status</th><th /></tr></thead><tbody>{rows.map((row) => { const amount = array(row, 'stockLevels').reduce((n, level) => n + num(level, 'availableQuantity'), 0); const cat = child(row, 'category'); return <tr key={txt(row, 'id')} onClick={() => onSelect(row)}><td className="mono sku">{txt(row, 'sku')}</td><td><strong>{txt(row, 'name')}</strong><small className="table-sub">{txt(row, 'unitOfMeasure')}</small></td><td>{txt(cat, 'name', 'Uncategorized')}</td><td className={amount <= num(row, 'reorderLevel') ? 'qty-negative' : ''}>{count(amount)} <small>units</small></td><td>{count(num(row, 'reorderLevel'))}</td><td>{money(String(row.costPrice || 0))}</td><td><StatusBadge status={row.isActive ? 'active' : 'inactive'} /></td><td><button className="row-more" onClick={(e) => { e.stopPropagation(); onSelect(row); }}>···</button></td></tr>; })}</tbody></table>;
  if (view === 'stock') return <table><thead><tr><th>Product</th><th>SKU</th><th>Warehouse</th><th>Available</th><th>Reserved</th><th>Damaged</th><th>Stock status</th></tr></thead><tbody>{rows.map((row) => { const product = child(row, 'product'); const place = child(row, 'warehouse'); const available = num(row, 'availableQuantity'); return <tr key={txt(row, 'id')} onClick={() => onSelect(row)}><td><strong>{txt(product, 'name')}</strong></td><td className="mono sku">{txt(product, 'sku')}</td><td>{txt(place, 'name')}</td><td>{count(available)} {txt(product, 'unitOfMeasure')}</td><td>{count(num(row, 'reservedQuantity'))}</td><td>{count(num(row, 'damagedQuantity'))}</td><td><StatusBadge status={available === 0 ? 'out of stock' : available <= num(product, 'reorderLevel') ? 'low stock' : 'healthy'} /></td></tr>; })}</tbody></table>;
  if (view === 'ledger') return <ActivityTable rows={rows} loading={false} openRecord={onSelect} />;
  if (view === 'warehouses') return <table><thead><tr><th>Warehouse</th><th>Location</th><th>Stock records</th><th>Status</th><th>Created</th></tr></thead><tbody>{rows.map((row) => <tr key={txt(row, 'id')} onClick={() => onSelect(row)}><td><div className="activity-product"><span className="warehouse-symbol">⌂</span><div><strong>{txt(row, 'name')}</strong><small>{txt(row, 'address', 'No address added')}</small></div></div></td><td>{txt(row, 'location', '—')}</td><td>{numericValue(child(row, '_count').stockLevels)}</td><td><StatusBadge status={row.isActive ? 'active' : 'inactive'} /></td><td>{date(txt(row, 'createdAt'))}</td></tr>)}</tbody></table>;
  if (view === 'team') return <table><thead><tr><th>Team member</th><th>Role</th><th>Status</th><th>Joined</th><th /></tr></thead><tbody>{rows.map((row) => { const email = txt(row, 'email'); const first = txt(row, 'firstName'); const last = txt(row, 'lastName'); return <tr key={txt(row, 'id')} onClick={() => onSelect(row)}><td><div className="activity-product"><span className="team-avatar">{(first || email).slice(0, 1).toUpperCase()}</span><div><strong>{[first, last].filter(Boolean).join(' ') || email}</strong><small>{email}</small></div></div></td><td>{actorRole === 'admin' ? <select aria-label={`Change ${email} role`} className="role-select" value={txt(row, 'role')} onClick={(e) => e.stopPropagation()} onChange={(e) => onAction(txt(row, 'id'), `role:${e.target.value}`)}><option value="admin">Admin</option><option value="manager">Manager</option><option value="staff">Staff</option></select> : <span className="role-label">{titleCase(txt(row, 'role'))}</span>}</td><td><StatusBadge status={txt(row, 'status')} /></td><td>{date(txt(row, 'createdAt'))}</td><td>{actorRole === 'admin' && txt(row, 'status') === 'active' && <button className="tiny-action" onClick={(e) => { e.stopPropagation(); onAction(txt(row, 'id'), 'disable'); }}>Disable</button>}</td></tr>; })}</tbody></table>;
  const isReceipt = view === 'receipts'; const isDelivery = view === 'deliveries'; const isTransfer = view === 'transfers'; const isAdjustment = view === 'adjustments';
  return <table><thead><tr><th>Reference</th><th>{isReceipt ? 'Supplier' : isTransfer ? 'Route' : isAdjustment ? 'Warehouse' : 'Sales order'}</th><th>Items</th><th>{isReceipt || isDelivery ? 'Warehouse' : 'Created'}</th><th>Status</th><th>Created</th><th /></tr></thead><tbody>{rows.map((row) => { const reference = txt(row, 'receiptNumber') || txt(row, 'deliveryNumber') || txt(row, 'transferNumber') || txt(row, 'adjustmentNumber'); const status = txt(row, 'status'); const actions = status === 'draft' ? isTransfer || isAdjustment ? ['approve'] : isDelivery ? ['pick'] : ['confirm'] : isDelivery && status === 'picking' ? ['pack'] : isDelivery && status === 'packed' ? ['confirm'] : isTransfer && status === 'approved' ? ['confirm'] : isReceipt && status === 'waiting' ? ['confirm'] : []; const supplier = child(row, 'supplier'); const source = child(row, 'fromWarehouse'); const destination = child(row, 'toWarehouse'); const place = child(row, 'warehouse'); const lines = array(row, 'items'); const secondary = isReceipt ? txt(supplier, 'name', '—') : isTransfer ? `${txt(source, 'name')} → ${txt(destination, 'name')}` : isAdjustment ? txt(place, 'name') : txt(row, 'salesOrderId', '—'); return <tr key={txt(row, 'id')} onClick={() => onSelect(row)}><td className="mono"><strong>{reference}</strong></td><td>{secondary}</td><td>{count(lines.length)} lines <small className="table-sub">{count(lines.reduce((n, item) => n + num(item, 'quantityOrdered') + num(item, 'quantity'), 0))} units</small></td><td>{isReceipt || isDelivery ? txt(place, 'name') : isTransfer ? date(txt(row, 'createdAt')) : row.createdById ? 'Cycle count' : '—'}</td><td><StatusBadge status={status} /></td><td>{date(txt(row, 'createdAt'))}</td><td><div className="table-actions">{actions.slice(0, 1).map((action) => <button className="tiny-action" key={action} onClick={(e) => { e.stopPropagation(); onAction(txt(row, 'id'), action); }}>{titleCase(action)}</button>)}<button className="row-more" onClick={(e) => { e.stopPropagation(); onSelect(row); }}>···</button></div></td></tr>; })}</tbody></table>;
}
function StatusBadge({ status }: { status: string }) { const tone = ['done', 'delivered', 'completed', 'approved', 'active', 'healthy'].includes(status) ? 'good' : ['draft', 'inactive'].includes(status) ? 'neutral' : ['out of stock', 'disabled'].includes(status) ? 'bad' : 'warning'; return <span className={`status-badge badge-${tone}`}><i />{titleCase(status)}</span>; }
function EmptyState({ title, text, action, actionLabel }: { title: string; text: string; action?: () => void; actionLabel?: string }) { return <div className="empty-state"><span className="empty-icon">⌁</span><strong>{title}</strong><p>{text}</p>{action && <button className="button button-primary" onClick={action}>{actionLabel || 'Create'}</button>}</div>; }

function DocumentModal({ type, selected, busy, onRole, onClose, onSubmit }: { type: View; selected: AnyRow | null; busy: boolean; onRole: string; onClose: () => void; onSubmit: (payload: AnyRow) => Promise<void> }) {
  const [products, setProducts] = useState<AnyRow[]>([]); const [warehouses, setWarehouses] = useState<AnyRow[]>([]); const [suppliers, setSuppliers] = useState<AnyRow[]>([]); const [categories, setCategories] = useState<AnyRow[]>([]); const [lines, setLines] = useState([{ productId: '', quantity: 1, countedQuantity: 0, unitPrice: 0 }]);
  useEffect(() => { api('products?limit=500').then((result) => setProducts(result.data || [])).catch(() => undefined); api('warehouses').then(setWarehouses).catch(() => undefined); api('suppliers').then(setSuppliers).catch(() => undefined); api('categories').then(setCategories).catch(() => undefined); }, []);
  const title = selected ? `Edit ${singular(type)}` : `New ${singular(type)}`;
  const submit = async (event: FormEvent<HTMLFormElement>) => { event.preventDefault(); const form = new FormData(event.currentTarget); const raw = { warehouseId: String(form.get('warehouseId') || ''), supplierId: String(form.get('supplierId') || '') || null, notes: String(form.get('notes') || ''), purchaseOrderId: String(form.get('purchaseOrderId') || ''), salesOrderId: String(form.get('salesOrderId') || ''), fromWarehouseId: String(form.get('fromWarehouseId') || ''), toWarehouseId: String(form.get('toWarehouseId') || '') };
    const validLines = lines.filter((line) => line.productId);
    const items = validLines.map((line) => type === 'adjustments' ? { productId: line.productId, countedQuantity: Number(line.countedQuantity), reason: 'Cycle count' } : { productId: line.productId, quantity: Number(line.quantity), unitPrice: Number(line.unitPrice || 0) });
    if (['receipts', 'deliveries', 'transfers', 'adjustments'].includes(type) && validLines.length === 0) { window.alert('Add at least one product line.'); return; }
    if (type === 'transfers') await onSubmit({ fromWarehouseId: raw.fromWarehouseId, toWarehouseId: raw.toWarehouseId, notes: raw.notes, items });
    else if (type === 'adjustments') await onSubmit({ warehouseId: raw.warehouseId, notes: raw.notes, items });
    else if (type === 'team' && onRole === 'admin' && selected) await onSubmit({ firstName: String(form.get('firstName') || '').trim() || undefined, lastName: String(form.get('lastName') || '').trim() || undefined, role: String(form.get('role') || 'staff') });
    else if (type === 'team' && onRole === 'admin') await onSubmit({ email: String(form.get('email') || ''), role: String(form.get('role') || 'staff') });
    else if (type === 'team') return;
    else if (type === 'categories') await onSubmit({ name: String(form.get('name') || ''), description: String(form.get('description') || ''), ...(selected ? { id: selected.id } : {}) });
    else if (type === 'suppliers') await onSubmit({ name: String(form.get('name') || ''), email: String(form.get('email') || ''), phone: String(form.get('phone') || ''), address: String(form.get('address') || ''), ...(selected ? { id: selected.id } : {}) });
    else if (type === 'warehouses') await onSubmit({ name: String(form.get('name') || ''), location: String(form.get('location') || ''), address: String(form.get('address') || ''), ...(selected ? { id: selected.id, isActive: String(form.get('isActive')) === 'true' } : {}) });
    else if (type === 'products') await onSubmit({ sku: String(form.get('sku') || ''), name: String(form.get('name') || ''), description: String(form.get('description') || ''), categoryId: String(form.get('categoryId') || '') || null, unitOfMeasure: String(form.get('unitOfMeasure') || 'units'), costPrice: Number(form.get('costPrice') || 0), sellingPrice: Number(form.get('sellingPrice') || 0), reorderLevel: Number(form.get('reorderLevel') || 0), reorderQuantity: Number(form.get('reorderQuantity') || 50), ...(selected ? { id: selected.id, isActive: String(form.get('isActive')) === 'true' } : {}) });
    else await onSubmit({ ...raw, items });
  };
  return <div className="modal-scrim" role="presentation" onMouseDown={(e) => { if (e.target === e.currentTarget) onClose(); }}><section className="form-modal" role="dialog" aria-modal="true" aria-labelledby="form-title"><div className="modal-heading"><div><span className="modal-kicker">WORKSPACE RECORD</span><h2 id="form-title">{title}</h2></div><button className="icon-action" onClick={onClose} aria-label="Close">×</button></div><form onSubmit={submit}><div className="modal-body">
    {type === 'products' ? <><Field label="Product name" name="name" placeholder="e.g. Stainless steel screws" required defaultValue={selected?.name} /><div className="form-grid"><Field label="SKU" name="sku" placeholder="STL-SCR-001" required defaultValue={selected?.sku} /><SelectField label="Category" name="categoryId" options={categories} defaultValue={selected?.categoryId} /></div><Field label="Description" name="description" placeholder="Useful details about the item" textarea defaultValue={selected?.description} /><div className="form-grid"><Field label="Unit of measure" name="unitOfMeasure" placeholder="units" defaultValue={selected?.unitOfMeasure || 'units'} /><Field label="Cost price" name="costPrice" type="number" placeholder="0.00" defaultValue={selected?.costPrice || 0} /></div><div className="form-grid"><Field label="Selling price" name="sellingPrice" type="number" placeholder="0.00" defaultValue={selected?.sellingPrice || 0} /><Field label="Reorder at" name="reorderLevel" type="number" placeholder="10" defaultValue={selected?.reorderLevel ?? 10} /></div><Field label="Reorder quantity" name="reorderQuantity" type="number" placeholder="50" defaultValue={selected?.reorderQuantity ?? 50} />{selected && <><SelectField label="Catalog status" name="isActive" options={[{ id: 'true', name: 'Active' }, { id: 'false', name: 'Inactive' }]} defaultValue={String(selected.isActive !== false)} /><div className="form-note">Product details are updated in place. Stock quantities stay in the ledger.</div></>}</>
    : type === 'warehouses' ? <><Field label="Warehouse name" name="name" placeholder="e.g. Northside warehouse" required defaultValue={selected?.name} /><Field label="Location" name="location" placeholder="City or region" defaultValue={selected?.location} /><Field label="Address" name="address" placeholder="Street address" textarea defaultValue={selected?.address} />{selected && <SelectField label="Warehouse status" name="isActive" options={[{ id: 'true', name: 'Active' }, { id: 'false', name: 'Inactive' }]} defaultValue={String(selected.isActive !== false)} />}</>


    : type === 'team' && onRole === 'admin' && selected ? <><div className="form-note">{selected.email}</div><div className="form-grid"><Field label="First name" name="firstName" placeholder="First name" defaultValue={selected.firstName || ''} /><Field label="Last name" name="lastName" placeholder="Last name" defaultValue={selected.lastName || ''} /></div><SelectField label="Workspace role" name="role" options={[{ id: 'admin', name: 'Admin' }, { id: 'manager', name: 'Manager' }, { id: 'staff', name: 'Staff' }]} required defaultValue={selected.role} /><div className="form-note">Name and role changes apply to this workspace profile. The email address is managed by the sign-in provider.</div></>
    : type === 'team' && onRole === 'admin' ? <><Field label="Email address" name="email" type="email" placeholder="colleague@company.com" required /><SelectField label="Workspace role" name="role" options={[{ id: 'staff', name: 'Staff' }, { id: 'manager', name: 'Manager' }]} required /><div className="form-note">Clerk sends the invitation. The invitee will join this workspace with the selected role after they accept and sign in.</div></>
    : type === 'team' ? <div className="form-note">Only workspace admins can invite members.</div>
    : type === 'categories' ? <><Field label="Category name" name="name" placeholder="e.g. Components" required defaultValue={selected?.name} /><Field label="Description" name="description" placeholder="What belongs in this category?" textarea defaultValue={selected?.description} /></>
    : type === 'suppliers' ? <><Field label="Supplier name" name="name" placeholder="e.g. Acme Industrial Supply" required defaultValue={selected?.name} /><div className="form-grid"><Field label="Email" name="email" type="email" placeholder="orders@supplier.com" defaultValue={selected?.email} /><Field label="Phone" name="phone" type="tel" placeholder="+1 555 010 0000" defaultValue={selected?.phone} /></div><Field label="Address" name="address" placeholder="Street and city" textarea defaultValue={selected?.address} /></>
    : <>
      {type === 'transfers' ? <div className="form-grid"><SelectField label="From warehouse" name="fromWarehouseId" options={warehouses} required /><SelectField label="To warehouse" name="toWarehouseId" options={warehouses} required /></div> : <SelectField label="Warehouse" name="warehouseId" options={warehouses} required />}
      {type === 'receipts' && <div className="form-grid"><SelectField label="Supplier" name="supplierId" options={suppliers} /><Field label="Purchase order" name="purchaseOrderId" placeholder="PO-1042" /></div>}
      {type === 'deliveries' && <Field label="Sales order" name="salesOrderId" placeholder="SO-2081" />}
      <div className="line-header"><div><strong>{type === 'adjustments' ? 'Counted products' : 'Product lines'}</strong><span>{type === 'adjustments' ? 'Enter physical counts for each product' : 'Add an item and quantity for this record'}</span></div><button type="button" className="text-link" onClick={() => setLines((current) => [...current, { productId: '', quantity: 1, countedQuantity: 0, unitPrice: 0 }])}>＋ Add line</button></div>
      {lines.map((line, index) => <div className="line-row" key={index}><select aria-label="Product" value={line.productId} onChange={(e) => setLines((current) => current.map((entry, i) => i === index ? { ...entry, productId: e.target.value } : entry))}><option value="">Choose product…</option>{products.map((product) => <option value={product.id} key={product.id}>{product.sku} · {product.name}</option>)}</select><input aria-label={type === 'adjustments' ? 'Counted quantity' : 'Quantity'} type="number" min={type === 'adjustments' ? 0 : 1} value={type === 'adjustments' ? line.countedQuantity : line.quantity} onChange={(e) => setLines((current) => current.map((entry, i) => i === index ? { ...entry, [type === 'adjustments' ? 'countedQuantity' : 'quantity']: Number(e.target.value) } : entry))} />{type === 'receipts' && <input aria-label="Unit cost" type="number" min="0" step="0.01" placeholder="Unit cost" value={line.unitPrice} onChange={(e) => setLines((current) => current.map((entry, i) => i === index ? { ...entry, unitPrice: Number(e.target.value) } : entry))} />}<button type="button" className="remove-line" onClick={() => setLines((current) => current.length > 1 ? current.filter((_, i) => i !== index) : current.map((entry, i) => i === index ? { ...entry, productId: '' } : entry))} aria-label="Remove line">×</button></div>)}
      <Field label="Notes" name="notes" placeholder="Add relevant details…" textarea />
    </>}
    </div><div className="modal-footer"><button type="button" className="button button-quiet" onClick={onClose}>Cancel</button><button disabled={busy} className="button button-primary" type="submit">{busy ? 'Saving…' : selected && ['products', 'warehouses', 'categories', 'suppliers', 'team'].includes(type) ? 'Save changes' : type === 'receipts' ? 'Save receipt' : type === 'deliveries' ? 'Create delivery' : type === 'transfers' ? 'Request transfer' : type === 'adjustments' ? 'Save count' : type === 'warehouses' ? 'Create warehouse' : type === 'team' ? (onRole === 'admin' ? 'Send invitation' : 'Admin access only') : type === 'categories' ? 'Create category' : type === 'suppliers' ? 'Create supplier' : 'Create product'}</button></div></form></section></div>;
}
function singular(view: View) { return ({ products: 'product', receipts: 'receipt', deliveries: 'delivery', transfers: 'transfer', adjustments: 'adjustment', warehouses: 'warehouse', categories: 'category', suppliers: 'supplier', team: 'invitation' } as Record<string, string>)[view] || 'record'; }
function Field({ label, name, placeholder, required, textarea, type = 'text', defaultValue }: { label: string; name: string; placeholder?: string; required?: boolean; textarea?: boolean; type?: string; defaultValue?: string | number }) { return <label className="form-field"><span>{label}{required && <i> · required</i>}</span>{textarea ? <textarea name={name} placeholder={placeholder} defaultValue={defaultValue} rows={3} /> : <input name={name} type={type} placeholder={placeholder} required={required} defaultValue={defaultValue} step={type === 'number' ? '0.01' : undefined} min={type === 'number' ? 0 : undefined} />}</label>; }
function SelectField({ label, name, options, required, defaultValue }: { label: string; name: string; options: AnyRow[]; required?: boolean; defaultValue?: string | null }) { const [value, setValue] = useState(defaultValue || ''); useEffect(() => { setValue(defaultValue || ''); }, [defaultValue, options]); return <label className="form-field"><span>{label}{required && <i> · required</i>}</span><select name={name} required={required} value={value} onChange={(event) => setValue(event.target.value)}><option value="">Select…</option>{options.map((option) => <option key={option.id} value={option.id}>{option.name}</option>)}</select></label>; }
function modalView(view: View): View | null { return ['products', 'warehouses', 'categories', 'suppliers', 'team'].includes(view) ? view : null; }

function DetailPanel({ item, onClose, onAction, onEdit, showDisable = false }: { item: AnyRow; onClose: () => void; onAction: (action: string) => void; onEdit?: () => void; showDisable?: boolean }) { const heading = txt(item, 'receiptNumber') || txt(item, 'deliveryNumber') || txt(item, 'transferNumber') || txt(item, 'adjustmentNumber') || txt(item, 'name') || txt(child(item, 'product'), 'name') || txt(child(item, 'product'), 'sku') || 'Record details'; const lines = array(item, 'items'); return <div className="modal-scrim detail-scrim" onMouseDown={(e) => { if (e.currentTarget === e.target) onClose(); }}><section className="detail-panel" role="dialog" aria-modal="true"><div className="detail-top"><div><span className="modal-kicker">RECORD DETAILS</span><h2>{heading}</h2></div><button className="icon-action" onClick={onClose} aria-label="Close details">×</button></div><div className="detail-content"><StatusBadge status={txt(item, 'status', item.isActive === false ? 'inactive' : 'active')} /><div className="detail-facts">{[['Created', date(txt(item, 'createdAt'))], ['Warehouse', txt(child(item, 'warehouse'), 'name') || txt(child(item, 'fromWarehouse'), 'name') || '—'], ['Supplier', txt(child(item, 'supplier'), 'name', '—')], ['Updated', date(txt(item, 'updatedAt') || txt(item, 'createdAt'))]].map(([label, value]) => <div key={label}><span>{label}</span><strong>{value}</strong></div>)}</div>{item.product && <div className="detail-facts"><div><span>SKU</span><strong className="mono">{item.product.sku}</strong></div><div><span>Available</span><strong>{count(item.availableQuantity)} units</strong></div><div><span>Reserved</span><strong>{count(item.reservedQuantity)} units</strong></div><div><span>Cost</span><strong>{money(item.product.costPrice)}</strong></div></div>}{item.sku && <div className="detail-facts"><div><span>SKU</span><strong className="mono">{item.sku}</strong></div><div><span>Category</span><strong>{item.category?.name || 'Uncategorized'}</strong></div><div><span>Unit cost</span><strong>{money(item.costPrice)}</strong></div><div><span>Reorder level</span><strong>{count(item.reorderLevel)} units</strong></div></div>}{item.email && <div className="detail-facts"><div><span>Email</span><strong>{item.email}</strong></div><div><span>Role</span><strong>{titleCase(item.role)}</strong></div></div>}{lines.length > 0 && <section className="detail-lines"><h3>Line items <span>{lines.length}</span></h3>{lines.map((line: AnyRow) => <div key={line.id} className="detail-line"><div><strong>{line.product?.name || line.productId}</strong><small>{line.product?.sku || ''}</small></div><span>{count(line.quantityOrdered || line.quantity || line.countedQuantity)} units</span></div>)}</section>}{item.notes && <section className="notes-block"><span>Notes</span><p>{item.notes}</p></section>}</div><div className="modal-footer">{onEdit && (!item.status || item.status === 'draft' || Boolean(item.email)) && <button className="button button-quiet" onClick={onEdit}>Edit</button>}{['draft', 'waiting'].includes(item.status) && item.receiptNumber && <button className="button button-primary" onClick={() => onAction('confirm')}>Confirm receipt</button>}{item.status === 'draft' && item.deliveryNumber && <button className="button button-primary" onClick={() => onAction('pick')}>Start picking</button>}{item.status === 'picking' && item.deliveryNumber && <button className="button button-primary" onClick={() => onAction('pack')}>Mark packed</button>}{item.status === 'packed' && item.deliveryNumber && <button className="button button-primary" onClick={() => onAction('confirm')}>Confirm delivery</button>}{item.status === 'draft' && item.transferNumber && <button className="button button-primary" onClick={() => onAction('approve')}>Approve transfer</button>}{item.status === 'approved' && item.transferNumber && <button className="button button-primary" onClick={() => onAction('confirm')}>Complete transfer</button>}{item.status === 'draft' && item.adjustmentNumber && <button className="button button-primary" onClick={() => onAction('approve')}>Approve adjustment</button>}{item.email && item.status === 'active' && showDisable && <button className="button button-quiet" onClick={() => onAction('disable')}>Disable member</button>}<button className="button button-quiet" onClick={onClose}>Close</button></div></section></div>; }

function ReportsView({ days, setDays }: { days: number; setDays: (v: number) => void }) { const [movements, setMovements] = useState<AnyRow[]>([]); const [variance, setVariance] = useState<AnyRow[]>([]); const [aging, setAging] = useState<AnyRow[]>([]); useEffect(() => { api(`reports/movements?days=${days}`).then(setMovements).catch(() => setMovements([])); api(`reports/variance?days=${days}`).then(setVariance).catch(() => setVariance([])); api('reports/aging').then(setAging).catch(() => setAging([])); }, [days]); const largest = Math.max(1, ...movements.map((r) => r.inbound + r.outbound)); return <><div className="report-controls"><label htmlFor="report-window">Reporting window</label><select id="report-window" value={days} onChange={(e) => setDays(Number(e.target.value))}><option value={30}>Last 30 days</option><option value={60}>Last 60 days</option><option value={90}>Last 90 days</option></select></div><div className="reports-grid"><section className="panel report-movement"><div className="panel-heading"><div><h2>Inventory movement</h2><p>Quantities received and shipped in this period</p></div><span className="small-live">{days} days</span></div>{movements.length ? <div className="report-chart">{movements.slice(-30).map((entry) => <div key={entry.date} title={`${entry.date}: ${entry.inbound} received, ${entry.outbound} shipped`}><i style={{ height: `${Math.max(3, entry.inbound / largest * 100)}%` }} /><b style={{ height: `${Math.max(3, entry.outbound / largest * 100)}%` }} /></div>)}</div> : <EmptyState title="No movements in this period" text="Completed receipts, deliveries, and adjustments appear here." />}<div className="chart-legend"><span><i className="legend-in" /> Received</span><span><i className="legend-out" /> Shipped</span></div></section><section className="panel report-variance"><div className="panel-heading"><div><h2>Count variances</h2><p>Approved physical stock corrections</p></div><span className="report-count">{variance.length} items</span></div>{variance.length ? variance.slice(0, 6).map((row) => <div className="variance-row" key={row.id}><div><strong>{row.product.name}</strong><small>{row.adjustment.warehouse.name} · {date(row.adjustment.createdAt)}</small></div><span className={row.variance >= 0 ? 'qty-positive' : 'qty-negative'}>{row.variance > 0 ? '+' : ''}{row.variance}</span></div>) : <p className="report-empty">No approved adjustments in this period.</p>}</section></div><section className="panel aging-panel"><div className="panel-heading"><div><h2>Stock on hand</h2><p>Current quantities and recorded value at cost</p></div><span className="report-count">{aging.length} positions</span></div>{aging.length ? <div className="table-scroll"><table><thead><tr><th>Product</th><th>Warehouse</th><th>On hand</th><th>Value</th><th>Last movement</th></tr></thead><tbody>{aging.slice(0, 12).map((row) => <tr key={`${row.productId}-${row.warehouse}`}><td><strong>{row.product}</strong><small className="table-sub">{row.sku}</small></td><td>{row.warehouse}</td><td>{count(row.quantity)}</td><td>{money(row.stockValue)}</td><td>{row.lastMovementAt ? date(row.lastMovementAt) : 'No movement'}</td></tr>)}</tbody></table></div> : <EmptyState title="No stock to report" text="Stock positions appear here after a receipt is confirmed." />}</section></>; }
